+export function streak(history = [], now = new Date()) {
+  const toLocalDay = (s) => {
+    if (typeof s !== "string") return null;
+    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
+    if (!m) return null;
+    const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
+    return Number.isNaN(d.getTime()) ? null : d;
+  };
+  const mondayOf = (d) => {
+    const m = new Date(d.getFullYear(), d.getMonth(), d.getDate());
+    m.setDate(m.getDate() - ((m.getDay() + 6) % 7));
+    return m.getTime();
+  };
+  const weeks = new Set();
+  const nowTime = now instanceof Date ? now.getTime() : new Date(now).getTime();
+  for (const g of Array.isArray(history) ? history : []) {
+    const d = toLocalDay(g?.date);
+    if (!d) continue;
+    if (d.getTime() > nowTime) continue;
+    weeks.add(mondayOf(d));
+  }
+  const thisWeek = mondayOf(now instanceof Date ? now : new Date(now));
+  const prevWeek = thisWeek - 7 * 86400000;
+  let start;
+  if (weeks.has(thisWeek)) start = thisWeek;
+  else if (weeks.has(prevWeek)) start = prevWeek;
+  else return 0;
+  let n = 0;
+  const cursor = new Date(start);
+  while (weeks.has(cursor.getTime())) { n += 1; cursor.setDate(cursor.getDate() - 7); }
+  return n;
+}
+
+export default streak;
