+export function streak(history = [], now = new Date()) {
+  const pad = (n) => String(n).padStart(2, "0");
+  const ymd = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
+  const today = ymd(now instanceof Date ? now : new Date(now));
+  const mondayOf = (d) => {
+    const c = new Date(d.getFullYear(), d.getMonth(), d.getDate());
+    c.setDate(c.getDate() - ((c.getDay() + 6) % 7));
+    return c;
+  };
+  const weeks = new Set();
+  for (const g of history || []) {
+    const s = g?.date;
+    if (typeof s !== "string" || s > today) continue;
+    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
+    if (!m) continue;
+    const d = new Date(+m[1], +m[2] - 1, +m[3]);
+    if (Number.isNaN(d.getTime())) continue;
+    if (ymd(d) !== s) continue;
+    weeks.add(mondayOf(d).getTime());
+  }
+  const cur = mondayOf(now instanceof Date ? now : new Date(now));
+  const key = (d) => new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
+  const has = (d) => weeks.has(key(d));
+  let start = null;
+  if (has(cur)) start = cur;
+  else {
+    const prev = new Date(cur);
+    prev.setDate(prev.getDate() - 7);
+    if (has(prev)) start = prev;
+    else return 0;
+  }
+  let n = 0;
+  for (let w = new Date(start); has(w); w.setDate(w.getDate() - 7)) n += 1;
+  return n;
+}
+
+export default streak;
