+export function streak(history = [], now = new Date()) {
+  const weeks = new Set();
+  const end = new Date(now);
+  for (const g of history || []) {
+    if (!g || typeof g.date !== "string") continue;
+    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(g.date);
+    if (!m) continue;
+    const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
+    if (Number.isNaN(d.getTime()) || d > end) continue;
+    weeks.add(startOfWeek(d).getTime());
+  }
+  let cur = startOfWeek(end);
+  if (!weeks.has(cur.getTime())) {
+    const prev = new Date(cur);
+    prev.setDate(prev.getDate() - 7);
+    if (!weeks.has(prev.getTime())) return 0;
+    cur = prev;
+  }
+  let n = 0;
+  for (;;) {
+    if (!weeks.has(cur.getTime())) break;
+    n += 1;
+    cur = new Date(cur);
+    cur.setDate(cur.getDate() - 7);
+  }
+  return n;
+}
+
+function startOfWeek(d) {
+  const c = new Date(d);
+  c.setHours(0, 0, 0, 0);
+  const dow = (c.getDay() + 6) % 7;
+  c.setDate(c.getDate() - dow);
+  return c;
+}
+
+export default streak;

